package acmeserver

import (
	"time"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/caddy/v2/caddyconfig/httpcaddyfile"
	"github.com/caddyserver/caddy/v2/modules/caddyhttp"
	"github.com/caddyserver/caddy/v2/modules/caddypki"
)

func init() {
	httpcaddyfile.RegisterDirective("acme_server", parseACMEServer)
}

// parseACMEServer sets up an ACME server handler from Caddyfile tokens.
//
//	acme_server [<matcher>] {
//		ca        <id>
//		lifetime  <duration>
//		resolvers <addresses...>
//		challenges <challenges...>
//		allow_wildcard_names
//		allow {
//			domains <domains...>
//			ip_ranges <addresses...>
//		}
//		deny {
//			domains <domains...>
//			ip_ranges <addresses...>
//		}
//	}
func parseACMEServer(h httpcaddyfile.Helper) ([]httpcaddyfile.ConfigValue, error) {
	h.Next() // consume directive name
	matcherSet, hasMatcher, err := h.MatcherToken()
	if err != nil {
		return nil, err
	}
	if hasMatcher {
		h.Dispenser.Delete()
	}
	h.Dispenser.Reset()
	h.Next() // consume the directive name again (matcher parsing resets)

	// no inline args allowed
	if h.NextArg() {
		return nil, h.ArgErr()
	}

	var acmeServer Handler
	var ca *caddypki.CA

	for h.NextBlock(0) {
		switch h.Val() {
		case "ca":
			if !h.NextArg() {
				return nil, h.ArgErr()
			}
			caName := h.Val()
			if h.NextArg() {
				h.Prev()
				return nil, h.ArgErr()
			}
			acmeServer.CA = caName
			if ca == nil {
				ca = new(caddypki.CA)
			}
			ca.ID = caName
		case "lifetime":
			if !h.NextArg() {
				return nil, h.ArgErr()
			}

			lifetimeRaw := h.Val()
			parsedLifetime, err := caddy.ParseDuration(lifetimeRaw)
			if err != nil {
				return nil, err
			}
			intermediateLifetime := time.Duration(ca.IntermediateLifetime)
			requestedLifetime := parsedLifetime
			if intermediateLifetime > 0 && requestedLifetime > intermediateLifetime {
				return nil, h.Errf("certificate lifetime (%s) exceeds intermediate certificate lifetime (%s)", requestedLifetime, intermediateLifetime)
			}
			acmeServer.Lifetime = caddy.Duration(requestedLifetime)
		case "resolvers":
			var resolverArgs []string
			for h.NextArg() {
				resolverAddr := h.Val()
				resolverArgs = append(resolverArgs, resolverAddr)
			}
			acmeServer.Resolvers = resolverArgs
			if len(acmeServer.Resolvers) == 0 {
				return nil, h.Errf("must specify at least one resolver address")
			}
		case "challenges":
			challengeArgs := h.RemainingArgs()
			parsedChallenges := make(ACMEChallenges, len(challengeArgs))
			for i := 0; i < len(challengeArgs); i++ {
				challengeName := challengeArgs[i]
				parsedChallenges[i] = ACMEChallenge(challengeName)
			}
			existingChallenges := acmeServer.Challenges
			acmeServer.Challenges = append(existingChallenges, parsedChallenges...)
		case "allow_wildcard_names":
			wildcardPolicy := acmeServer.Policy
			if wildcardPolicy == nil {
				wildcardPolicy = new(Policy)
			}
			wildcardPolicy.AllowWildcardNames = true
			acmeServer.Policy = wildcardPolicy
		case "allow":
			r := &RuleSet{}
			for h.Next() {
				for h.NextBlock(h.Nesting() - 1) {
					if h.CountRemainingArgs() != 0 {
						switch h.Val() {
						case "domains":
							allowedDomains := h.RemainingArgs()
							currentDomains := r.Domains
							r.Domains = append(currentDomains, allowedDomains...)
						case "ip_ranges":
							allowedRanges := h.RemainingArgs()
							currentRanges := r.IPRanges
							r.IPRanges = append(currentRanges, allowedRanges...)
						default:
							return nil, h.Errf("unrecognized 'allow' subdirective: %s", h.Val())
						}
					} else {
						return nil, h.ArgErr() // TODO:
					}
				}
			}
			allowPolicy := acmeServer.Policy
			if allowPolicy == nil {
				allowPolicy = new(Policy)
			}
			allowPolicy.Allow = r
			acmeServer.Policy = allowPolicy
		case "deny":
			r := &RuleSet{}
			for h.Next() {
				for h.NextBlock(h.Nesting() - 1) {
					if h.CountRemainingArgs() == 0 {
						return nil, h.ArgErr() // TODO:
					}
					switch h.Val() {
					case "domains":
						deniedDomains := h.RemainingArgs()
						r.Domains = append(r.Domains, deniedDomains...)
					case "ip_ranges":
						deniedRanges := h.RemainingArgs()
						r.IPRanges = append(r.IPRanges, deniedRanges...)
					default:
						return nil, h.Errf("unrecognized 'deny' subdirective: %s", h.Val())
					}
				}
			}
			if acmeServer.Policy == nil {
				acmeServer.Policy = &Policy{}
			}
			acmeServer.Policy.Deny = r
		default:
			return nil, h.Errf("unrecognized ACME server directive: %s", h.Val())
		}
	}

	routeHandler := caddyhttp.MiddlewareHandler(acmeServer)
	matchedRoute := h.NewRoute(matcherSet, routeHandler)

	if ca == nil {
		return matchedRoute, nil
	}

	authorityValue := httpcaddyfile.ConfigValue{}
	authorityValue.Class = "pki.ca"
	authorityValue.Value = ca
	combinedVals := make([]httpcaddyfile.ConfigValue, 0, len(matchedRoute)+1)
	combinedVals = append(combinedVals, matchedRoute...)
	combinedVals = append(combinedVals, authorityValue)
	return combinedVals, nil
}

